// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  random,
  interpolate,
} from '../remotionShim';


export type ConfettiPopProps = Record<string, any>;

const ConfettiPop: React.FC<ConfettiPopProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 5,
  particleCount = 150,
  gravity = 1.0,
  velocityMultiplier = 1.0,
  colors = [
    "#FF3B30",
    "#34C759",
    "#007AFF",
    "#FFCC00",
    "#FF2D55",
    "#AF52DE",
    "#FF9500",
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const durationInFrames = Math.max(1, durationInSeconds * fps);

  // Memoize particle properties so they remain perfectly deterministic and don't recalculate per frame
  const particles = useMemo(() => {
    return Array.from({ length: particleCount }).map((_, index) => {
      // Pick a random color from the provided palette
      const color = colors[Math.floor(random(`color-${index}`) * colors.length)];
      
      // Determine shape (square, circle, or streamer/rectangle)
      const shapeType = random(`shape-${index}`);
      let w = 10;
      let h = 10;
      let borderRadius = "0%";

      if (shapeType < 0.33) {
        // Square
        w = 8 + random(`sz-${index}`) * 10;
        h = w;
      } else if (shapeType < 0.66) {
        // Circle
        w = 8 + random(`sz-${index}`) * 10;
        h = w;
        borderRadius = "50%";
      } else {
        // Streamer
        w = 6 + random(`w-${index}`) * 6;
        h = 15 + random(`h-${index}`) * 20;
      }

      // Start clustered horizontally at the center-bottom, slightly randomized
      const startX = width / 2 + (random(`sx-${index}`) - 0.5) * width * 0.2;
      const startY = height + 50;

      // X velocity: wide spread outward to fill the canvas
      const vx0 = (random(`vx-${index}`) - 0.5) * width * 0.08 * velocityMultiplier;
      
      // Y velocity: powerful upward shoot
      const vy0 = -(height * 0.035 + random(`vy-${index}`) * height * 0.045) * velocityMultiplier;

      // Flutter properties for falling realism
      const flutterAmplitude = 10 + random(`fa-${index}`) * 40;
      const flutterFreq = 0.05 + random(`ff-${index}`) * 0.1;
      const flutterPhase = random(`fp-${index}`) * Math.PI * 2;

      // 3D Rotation speeds
      const rx = (random(`rx-${index}`) - 0.5) * 20;
      const ry = (random(`ry-${index}`) - 0.5) * 20;
      const rz = (random(`rz-${index}`) - 0.5) * 20;

      return {
        id: index,
        color,
        w,
        h,
        borderRadius,
        startX,
        startY,
        vx0,
        vy0,
        flutterAmplitude,
        flutterFreq,
        flutterPhase,
        rx,
        ry,
        rz,
      };
    });
  }, [particleCount, colors, width, height, velocityMultiplier]);

  // Global opacity fade-out at the very end of the animation
  const globalOpacity = interpolate(
    frame,
    [durationInFrames - 30, durationInFrames - 1],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        perspective: "1000px",
        overflow: "hidden",
      }}
    >
      {particles.map((p) => {
        const g = gravity * 1.5;
        const drag = 0.94; // Simulates horizontal air resistance

        // Calculate horizontal position with air resistance dampening
        const horizontalDistance = p.vx0 * ((1 - Math.pow(drag, frame)) / (1 - drag));
        
        // Add flutter to X axis for realistic falling
        const flutter = Math.sin(frame * p.flutterFreq + p.flutterPhase) * p.flutterAmplitude;
        const currentX = p.startX + horizontalDistance + flutter;
        
        // Parabolic vertical movement
        const currentY = p.startY + p.vy0 * frame + 0.5 * g * frame * frame;

        // Calculate continuous rotation
        const rotX = frame * p.rx;
        const rotY = frame * p.ry;
        const rotZ = frame * p.rz;

        return (
          <div
            key={p.id}
            style={{
              position: "absolute",
              left: currentX,
              top: currentY,
              width: p.w,
              height: p.h,
              backgroundColor: p.color,
              borderRadius: p.borderRadius,
              opacity: globalOpacity,
              transform: `translate(-50%, -50%) rotateX(${rotX}deg) rotateY(${rotY}deg) rotateZ(${rotZ}deg)`,
              transformStyle: "preserve-3d",
              transition: "none", // Strict rule: no CSS transitions
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

export default ConfettiPop;